package inicializacao.de.blocos.domain;public class Anime{    private String name;    private int[] episodes = new int[100];    {        System.out.println("Bloco de inicialização vazio");    }    public Anime(String name) {        this.name = name;    }    public Anime() {        System.out.println(episodes);        for (int i = 0; i < this.episodes.length; i++){            episodes[i] =  i + 1;            System.out.print(" " + this.episodes[i]);        }    }    public String getName() {        return name;    }}